diff --git a/db/migrations/010_run_status_both_ways.sql b/db/migrations/010_run_status_both_ways.sql
new file mode 100644
--- /dev/null
+++ b/db/migrations/010_run_status_both_ways.sql
@@ -0,0 +1,6 @@
+DROP TRIGGER IF EXISTS runs_status_column;
+CREATE TRIGGER runs_status_column AFTER UPDATE OF state ON runs
+BEGIN
+  UPDATE runs SET status = json_extract(NEW.state, '$.status') WHERE id = NEW.id;
+END;
+UPDATE runs SET status = json_extract(state, '$.status');
